var OPTS = { search: true, empty: 'No account history for this bill' };
var COLS = [
  { headerName: 'Pear ID', field: 'bill_id', link: true, cellRenderer: linkRenderer, comparator: numCmp, minWidth: 100 },
  { headerName: 'Start Date', field: 'start_date', valueFormatter: function(p){ return fmtDate(p.value); }, comparator: dateCmp },
  { headerName: 'End Date', field: 'end_date', valueFormatter: function(p){ return fmtDate(p.value); }, comparator: dateCmp },
  { headerName: 'Days Of Service', field: 'days_of_service', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Subcharges', field: 'subcharges', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Consumption', field: 'consumption', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Gen Consumption', field: 'gen_consumption', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Demand', field: 'demand', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Unit Cost', field: 'unit_cost', valueFormatter: function(p){ return dash(p.value); }, comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Load Factor', field: 'load_factor', comparator: numCmp, cellClass: 'num', headerClass: 'num' },
  { headerName: 'Estimated', field: 'estimated', valueFormatter: function(p){ return dash(p.value); } },
  { headerName: 'Rate Plan', field: 'rate_code', tooltipField: 'rate_code' }
];
// Themed list grid (client-side paging/search). COLS and OPTS are set above.
function fmtDate(v){
  if (!v) return '';
  var s = String(v);
  var m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s);
  if (m) return m[2] + '/' + m[3] + '/' + m[1];
  return s;
}
function dateKey(v){
  var s = String(v || ''), m;
  if ((m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s))) return Number(m[1] + m[2] + m[3]);
  if ((m = /^(\d{2})\/(\d{2})\/(\d{4})/.exec(s))) return Number(m[3] + m[1] + m[2]);
  return 0;
}
function dateCmp(a, b){ return dateKey(a) - dateKey(b); }
function numCmp(a, b){ return (Number(a) || 0) - (Number(b) || 0); }
function dash(v){ return (v === null || v === undefined || v === '') ? '-' : v; }
function linkRenderer(p){
  if (!p.data || p.value == null) return '';
  return '<a class="lnk" href="#" title="Open this bill in a new tab">' + p.value + '</a>';
}
function tickRenderer(p){
  if (!p.data || !isCurrent(p.data)) return '';
  return '<span class="tick" title="This bill">&#10003;</span>';
}
function isCurrent(r){ return r && M.current != null && String(r.bill_id) === String(M.current); }

var gridApi = null, M = {}, lastSig = '';
function rows(m){ return (m && Array.isArray(m.rows)) ? m.rows : []; }
function sig(m){ var r = rows(m); return (m && m.isLoading ? 'L' : '') + r.length + ':' + (r[0] && r[0].bill_id) + ':' + (m && m.current); }

function drawCount(){
  var n = gridApi ? gridApi.getDisplayedRowCount() : rows(M).length;
  document.getElementById('count').textContent = n.toLocaleString() + ' Records';
}

function csv(){
  var cols = COLS.filter(function(c){ return c.field && c.headerName; });
  function q(v){ v = v == null ? '' : String(v); return /[",\n]/.test(v) ? '"' + v.replace(/"/g, '""') + '"' : v; }
  var out = [cols.map(function(c){ return q(c.headerName); }).join(',')];
  gridApi.forEachNodeAfterFilterAndSort(function(n){
    out.push(cols.map(function(c){ var v = n.data[c.field]; return q(c.valueFormatter ? c.valueFormatter({ value: v, data: n.data }) : v); }).join(','));
  });
  return out.join('\n');
}

function render(){
  var div = document.getElementById('myGrid');
  div.innerHTML = '';
  gridApi = agGrid.createGrid(div, {
    columnDefs: COLS,
    rowData: rows(M),
    defaultColDef: { resizable: true, sortable: true, minWidth: 90, flex: 1 },
    pagination: true,
    paginationPageSize: 20,
    paginationPageSizeSelector: false,
    suppressCellFocus: true,
    tooltipShowDelay: 400,
    rowClassRules: { 'current': function(p){ return isCurrent(p.data); } },
    overlayNoRowsTemplate: '<span class="empty">' + OPTS.empty + '</span>',
    overlayLoadingTemplate: '<span class="empty">Loading…</span>',
    onCellClicked: function(e){
      if (!e.data || !e.colDef.link) return;
      if (e.event && e.event.preventDefault) e.event.preventDefault();
      appsmith.updateModel({ openBillId: e.data.bill_id });
      appsmith.triggerEvent('onOpenBill');
    },
    onModelUpdated: drawCount
  });
  if (M.isLoading) gridApi.showLoadingOverlay();
  lastSig = sig(M);
}

function update(m){
  M = m || {};
  if (!gridApi){ render(); drawCount(); return; }
  var s = sig(M);
  if (s === lastSig) return;
  lastSig = s;
  if (M.isLoading){ gridApi.showLoadingOverlay(); return; }
  gridApi.setGridOption('rowData', rows(M));
  gridApi.redrawRows();
  if (!rows(M).length) gridApi.showNoRowsOverlay(); else gridApi.hideOverlay();
  drawCount();
}

appsmith.onReady(function(){
  var s = document.getElementById('search');
  if (OPTS.search) s.addEventListener('input', function(e){ if (gridApi) gridApi.setGridOption('quickFilterText', e.target.value); });
  else s.style.display = 'none';
  document.getElementById('dl').addEventListener('click', function(){
    if (!gridApi) return;
    appsmith.updateModel({ csv: csv() });
    appsmith.triggerEvent('onCsvDownload');
  });
  update(appsmith.model);
  appsmith.onModelChange(update);
});

